CREATE FUNCTION __schema__.compute_task_state_bucket(p_task_id uuid) RETURNS text LANGUAGE sql STABLE AS $$ SELECT CASE WHEN t.closed_at IS NOT NULL THEN 'closed' WHEN t.escalated_at IS NOT NULL OR COALESCE(t.is_escalated, FALSE) IS TRUE THEN 'escalated' ELSE COALESCE( ( SELECT CASE WHEN stage_scan.state IN ( 'ready', 'in_progress', 'needs_review', 'review_approved' ) THEN stage_scan.state ELSE 'ready' END FROM task_stage_states stage_scan WHERE stage_scan.task_id = p_task_id AND stage_scan.state <> 'done' ORDER BY stage_scan.position LIMIT 1 ), 'ready' ) END FROM tasks t WHERE t.id = p_task_id $$;
CREATE FUNCTION __schema__.enforce_chat_attachments_bound_at_write_once() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.bound_at IS NOT NULL AND NEW.bound_at IS DISTINCT FROM OLD.bound_at THEN RAISE EXCEPTION 'chat_attachments.bound_at is write-once'; END IF; RETURN NEW; END; $$;
CREATE FUNCTION __schema__.gobby_maintenance_epoch_login_guard() RETURNS event_trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $$ DECLARE active_epoch UUID; supplied_epoch TEXT; BEGIN IF pg_catalog.pg_is_in_recovery() THEN RETURN; END IF; SELECT id INTO active_epoch FROM __schema__.maintenance_epochs WHERE released_at IS NULL; IF active_epoch IS NULL THEN RETURN; END IF; supplied_epoch := pg_catalog.current_setting('gobby.maintenance_epoch', TRUE); IF supplied_epoch IS DISTINCT FROM active_epoch::TEXT THEN RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'Gobby hub maintenance is active; use ' '`gobby hub-maintenance status` to inspect it or ' '`gobby hub-maintenance resume` from the operator shell.'; END IF; END; $$;
CREATE FUNCTION __schema__.memories_tags_to_text(tags jsonb) RETURNS text LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$ SELECT COALESCE(string_agg(value, ' ' ORDER BY ord), '') FROM jsonb_array_elements_text(tags) WITH ORDINALITY AS t(value, ord); $$;
CREATE FUNCTION __schema__.refresh_task_state_bucket(p_task_id uuid) RETURNS void LANGUAGE plpgsql AS $$ BEGIN UPDATE tasks SET state_bucket = compute_task_state_bucket(p_task_id) WHERE id = p_task_id; END; $$;
CREATE FUNCTION __schema__.refresh_task_state_bucket_from_stage() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'DELETE' THEN PERFORM refresh_task_state_bucket(OLD.task_id); RETURN OLD; END IF; PERFORM refresh_task_state_bucket(NEW.task_id); IF TG_OP = 'UPDATE' AND OLD.task_id IS DISTINCT FROM NEW.task_id THEN PERFORM refresh_task_state_bucket(OLD.task_id); END IF; RETURN NEW; END; $$;
CREATE FUNCTION __schema__.refresh_task_state_bucket_from_task() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM refresh_task_state_bucket(NEW.id); RETURN NEW; END; $$;
CREATE FUNCTION __schema__.touch_chat_attachments_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at THEN NEW.updated_at := NOW(); END IF; RETURN NEW; END; $$;
