CREATE TABLE __schema__.token_events (cache_creation_tokens integer DEFAULT 0 NOT NULL, cache_read_tokens integer DEFAULT 0 NOT NULL, context_window integer, created_at timestamp with time zone DEFAULT now() NOT NULL, event_at timestamp with time zone NOT NULL, id integer NOT NULL, input_tokens integer DEFAULT 0 NOT NULL, message_id text, metadata jsonb, model text, model_family text, origin text NOT NULL, output_tokens integer DEFAULT 0 NOT NULL, project_id uuid, session_id uuid NOT NULL, source text NOT NULL);
CREATE TABLE __schema__.tool_metrics (avg_latency_ms real, call_count integer DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, failure_count integer DEFAULT 0 NOT NULL, id uuid NOT NULL, last_called_at timestamp with time zone, project_id uuid NOT NULL, server_name text NOT NULL, success_count integer DEFAULT 0 NOT NULL, tool_name text NOT NULL, total_latency_ms real DEFAULT 0 NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE __schema__.tool_metrics_daily (avg_latency_ms real, call_count integer DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, date date NOT NULL, failure_count integer DEFAULT 0 NOT NULL, id integer NOT NULL, project_id uuid NOT NULL, server_name text NOT NULL, success_count integer DEFAULT 0 NOT NULL, tool_name text NOT NULL, total_latency_ms real DEFAULT 0 NOT NULL);
CREATE TABLE __schema__.tool_result_chunks (content text NOT NULL, end_offset integer NOT NULL, id uuid NOT NULL, ordinal integer NOT NULL, result_id uuid NOT NULL, start_offset integer NOT NULL);
CREATE TABLE __schema__.tool_results (CONSTRAINT tool_results_content_kind_check CHECK ((content_kind = ANY (ARRAY['json'::text, 'text'::text]))), content text NOT NULL, content_kind text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, id uuid NOT NULL, project_id uuid NOT NULL, server_name text NOT NULL, session_id uuid, stored_chars integer NOT NULL, tool_name text NOT NULL, total_chars bigint NOT NULL);
CREATE TABLE __schema__.tool_schema_hashes (created_at timestamp with time zone DEFAULT now() NOT NULL, id integer NOT NULL, last_verified_at timestamp with time zone DEFAULT now() NOT NULL, project_id uuid NOT NULL, schema_hash text NOT NULL, server_name text NOT NULL, tool_name text NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE __schema__.tools (created_at timestamp with time zone DEFAULT now() NOT NULL, description text, id uuid NOT NULL, input_schema jsonb, mcp_server_id uuid NOT NULL, name text NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE __schema__.unmodeled_observation_events (first_seen_at timestamp with time zone DEFAULT now() NOT NULL, id uuid NOT NULL, kind text NOT NULL, last_seen_at timestamp with time zone DEFAULT now() NOT NULL, name text NOT NULL, sample_hash text NOT NULL, sample_keys jsonb DEFAULT '[]'::jsonb NOT NULL, server_name text DEFAULT ''::text NOT NULL, session_id uuid, source text NOT NULL, source_line integer, source_ref text DEFAULT ''::text NOT NULL, tool_type text DEFAULT ''::text NOT NULL);
CREATE TABLE __schema__.unmodeled_observations (CONSTRAINT unmodeled_observations_count_check CHECK ((count >= 0)), count bigint DEFAULT 0 NOT NULL, example_session_id uuid, first_seen_at timestamp with time zone DEFAULT now() NOT NULL, kind text NOT NULL, last_seen_at timestamp with time zone DEFAULT now() NOT NULL, name text NOT NULL, sample_hash text NOT NULL, sample_keys jsonb DEFAULT '[]'::jsonb NOT NULL, server_name text DEFAULT ''::text NOT NULL, source text NOT NULL, tool_type text DEFAULT ''::text NOT NULL);
CREATE TABLE __schema__.workflow_audit_log ("timestamp" timestamp with time zone DEFAULT now() NOT NULL, condition text, context jsonb, event_type text NOT NULL, id integer NOT NULL, reason text, result text NOT NULL, rule_id text, session_id uuid NOT NULL, step text NOT NULL, tool_name text);
CREATE TABLE __schema__.workflow_definitions (canvas_json jsonb, created_at timestamp with time zone DEFAULT now() NOT NULL, definition_json jsonb NOT NULL, deleted_at timestamp with time zone, description text, enabled boolean DEFAULT true, enabled_user_modified boolean DEFAULT false NOT NULL, id uuid NOT NULL, name text NOT NULL, priority integer DEFAULT 100, project_id uuid, source text DEFAULT 'installed'::text, sources jsonb, tags jsonb, updated_at timestamp with time zone DEFAULT now() NOT NULL, version text DEFAULT '1.0'::text, workflow_type text DEFAULT 'workflow'::text NOT NULL);
CREATE TABLE __schema__.workflow_instances (context_injected boolean DEFAULT false, created_at timestamp with time zone DEFAULT now() NOT NULL, current_step text, enabled boolean DEFAULT true NOT NULL, id uuid NOT NULL, priority integer DEFAULT 100 NOT NULL, session_id uuid NOT NULL, step_action_count integer DEFAULT 0, step_entered_at timestamp with time zone, total_action_count integer DEFAULT 0, updated_at timestamp with time zone DEFAULT now() NOT NULL, variables jsonb DEFAULT '{}'::jsonb, workflow_name text NOT NULL);
CREATE TABLE __schema__.worktrees (agent_session_id uuid, base_branch text DEFAULT 'main'::text, branch_name text NOT NULL, cleanup_after timestamp with time zone, created_at timestamp with time zone DEFAULT now() NOT NULL, id uuid NOT NULL, last_activity_at timestamp with time zone, machine_id uuid NOT NULL, merge_state text, merged_at timestamp with time zone, project_id uuid NOT NULL, status text DEFAULT 'active'::text, task_id uuid, updated_at timestamp with time zone DEFAULT now() NOT NULL, workspace_role text DEFAULT 'task'::text NOT NULL, worktree_path text NOT NULL);
CREATE TRIGGER task_stage_states_state_bucket_ad AFTER DELETE ON __schema__.task_stage_states FOR EACH ROW EXECUTE FUNCTION __schema__.refresh_task_state_bucket_from_stage();
CREATE TRIGGER task_stage_states_state_bucket_ai AFTER INSERT ON __schema__.task_stage_states FOR EACH ROW EXECUTE FUNCTION __schema__.refresh_task_state_bucket_from_stage();
CREATE TRIGGER task_stage_states_state_bucket_au AFTER UPDATE OF state, "position" ON __schema__.task_stage_states FOR EACH ROW EXECUTE FUNCTION __schema__.refresh_task_state_bucket_from_stage();
CREATE TRIGGER tasks_state_bucket_ai AFTER INSERT ON __schema__.tasks FOR EACH ROW EXECUTE FUNCTION __schema__.refresh_task_state_bucket_from_task();
CREATE TRIGGER tasks_state_bucket_au AFTER UPDATE OF closed_at, escalated_at, is_escalated ON __schema__.tasks FOR EACH ROW EXECUTE FUNCTION __schema__.refresh_task_state_bucket_from_task();
CREATE TRIGGER trg_chat_attachments_bound_at_write_once BEFORE UPDATE OF bound_at ON __schema__.chat_attachments FOR EACH ROW EXECUTE FUNCTION __schema__.enforce_chat_attachments_bound_at_write_once();
CREATE TRIGGER trg_chat_attachments_updated_at_touch BEFORE UPDATE ON __schema__.chat_attachments FOR EACH ROW EXECUTE FUNCTION __schema__.touch_chat_attachments_updated_at();
CREATE UNIQUE INDEX idx_build_profiles_active_unique ON __schema__.build_profiles USING btree (name, project_id, source) NULLS NOT DISTINCT WHERE (deleted_at IS NULL);
CREATE UNIQUE INDEX idx_clones_path ON __schema__.clones USING btree (machine_id, clone_path);
CREATE UNIQUE INDEX idx_comms_messages_channel_platform_message ON __schema__.comms_messages USING btree (channel_id, platform_message_id) WHERE (platform_message_id IS NOT NULL);
CREATE UNIQUE INDEX idx_cron_runs_one_active_per_job ON __schema__.cron_runs USING btree (cron_job_id) WHERE (status = ANY (ARRAY['pending'::text, 'running'::text]));
CREATE UNIQUE INDEX idx_mcp_servers_name_project ON __schema__.mcp_servers USING btree (name, project_id);
CREATE UNIQUE INDEX idx_memory_dream_runs_single_running ON __schema__.memory_dream_runs USING btree (status) WHERE (status = 'running'::text);
CREATE UNIQUE INDEX idx_pending_interactions_active ON __schema__.pending_interactions USING btree (session_id, kind) WHERE (status = 'pending'::text);
CREATE UNIQUE INDEX idx_plan_review_evidence_active_path ON __schema__.plan_review_evidence USING btree (project_id, plan_path) WHERE ((finalized_at IS NULL) AND (expired_at IS NULL));
CREATE UNIQUE INDEX idx_plan_review_evidence_dispatch_run ON __schema__.plan_review_evidence USING btree (dispatch_run_id) WHERE (dispatch_run_id IS NOT NULL);
CREATE UNIQUE INDEX idx_plan_review_evidence_interactive_round ON __schema__.plan_review_evidence USING btree (session_id, plan_path, round_number) WHERE ((session_id IS NOT NULL) AND (expired_at IS NULL));
CREATE UNIQUE INDEX idx_plan_review_evidence_stage_round ON __schema__.plan_review_evidence USING btree (task_id, stage, round_number) WHERE ((task_id IS NOT NULL) AND (expired_at IS NULL));
CREATE UNIQUE INDEX idx_projects_active_name ON __schema__.projects USING btree (name) WHERE (deleted_at IS NULL);
CREATE UNIQUE INDEX idx_recall_signal_requests_request_id ON __schema__.recall_signal_requests USING btree (recall_request_id);
CREATE UNIQUE INDEX idx_session_skills_unique ON __schema__.session_skills USING btree (session_id, skill_name);
CREATE UNIQUE INDEX idx_sessions_seq_num ON __schema__.sessions USING btree (project_id, seq_num);
CREATE UNIQUE INDEX idx_sessions_unique ON __schema__.sessions USING btree (external_id, machine_id, source, project_id, session_type) NULLS NOT DISTINCT;
CREATE UNIQUE INDEX idx_task_stage_states_position ON __schema__.task_stage_states USING btree (task_id, "position");
CREATE UNIQUE INDEX idx_tasks_github_issue_link ON __schema__.tasks USING btree (project_id, github_repo, github_issue_number) WHERE ((github_repo IS NOT NULL) AND (github_issue_number IS NOT NULL));
CREATE UNIQUE INDEX idx_tasks_seq_num ON __schema__.tasks USING btree (project_id, seq_num);
CREATE UNIQUE INDEX idx_token_events_dedup ON __schema__.token_events USING btree (session_id, message_id) WHERE (message_id IS NOT NULL);
CREATE UNIQUE INDEX idx_worktrees_branch ON __schema__.worktrees USING btree (project_id, branch_name, machine_id);
CREATE UNIQUE INDEX idx_worktrees_path ON __schema__.worktrees USING btree (machine_id, worktree_path);
CREATE UNIQUE INDEX maintenance_epochs_one_open ON __schema__.maintenance_epochs USING btree ((true)) WHERE (released_at IS NULL);
